const now = new Date();
const weekStart = new Date(now);
weekStart.setDate(weekStart.getDate() - 7);

const repoFull = ($env.GITHUB_REPO || '').trim();
if (!/^[a-zA-Z0-9._-]+\/[a-zA-Z0-9._-]+$/.test(repoFull)) {
  throw new Error('Set GITHUB_REPO to owner/repo with GitHub-safe characters only.');
}
const [owner, repo] = repoFull.split('/');

const githubToken = ($env.GITHUB_TOKEN || '').trim();
const anthropicKey = ($env.ANTHROPIC_API_KEY || '').trim();
if (!githubToken) throw new Error('Set GITHUB_TOKEN with repo read access.');
if (!anthropicKey) throw new Error('Set ANTHROPIC_API_KEY.');

const language = (($env.SUMMARY_LANGUAGE || 'EN').trim().toUpperCase() === 'FR') ? 'FR' : 'EN';
const deliveryChannel = (($env.DELIVERY_CHANNEL || '').trim().toLowerCase());
const discordUrl = ($env.DISCORD_WEBHOOK_URL || '').trim();
const slackUrl = ($env.SLACK_WEBHOOK_URL || '').trim();
const emailTo = ($env.SUMMARY_EMAIL_TO || '').trim();

let channel = deliveryChannel;
if (!channel) {
  if (discordUrl) channel = 'discord';
  else if (slackUrl) channel = 'slack';
  else if (emailTo) channel = 'email';
}

if (!['discord', 'slack', 'email'].includes(channel)) {
  throw new Error('Set DELIVERY_CHANNEL to discord, slack, or email (and the matching destination variable).');
}
if (channel === 'discord' && !discordUrl) throw new Error('DELIVERY_CHANNEL=discord requires DISCORD_WEBHOOK_URL.');
if (channel === 'slack' && !slackUrl) throw new Error('DELIVERY_CHANNEL=slack requires SLACK_WEBHOOK_URL.');
if (channel === 'email' && !emailTo) throw new Error('DELIVERY_CHANNEL=email requires SUMMARY_EMAIL_TO.');

return [{
  json: {
    owner,
    repo,
    repoFullName: `${owner}/${repo}`,
    language,
    weekStart: weekStart.toISOString(),
    weekEnd: now.toISOString(),
    githubToken,
    anthropicApiKey: anthropicKey,
    deliveryChannel: channel,
    discordWebhookUrl: discordUrl,
    slackWebhookUrl: slackUrl,
    emailTo,
    emailFrom: ($env.SUMMARY_EMAIL_FROM || 'n8n@localhost').trim()
  }
}];

const config = $('Load Config').first().json;
const weekStart = new Date(config.weekStart);
const weekEnd = new Date(config.weekEnd);

const inWeek = (iso) => {
  if (!iso) return false;
  const d = new Date(iso);
  return d >= weekStart && d <= weekEnd;
};

const collectRecords = (nodeName) => {
  try {
    const items = $(nodeName).all();
    if (!items.length) return [];
    const rows = items.map((item) => item.json).filter((row) => row && typeof row === 'object');
    if (rows.length === 1 && Array.isArray(rows[0].items)) return rows[0].items;
    if (rows.length === 1 && Array.isArray(rows[0])) return rows[0];
    return rows;
  } catch (_) {
    return [];
  }
};

const commits = collectRecords('Fetch Commits')
  .filter((c) => inWeek(c.commit?.author?.date || c.commit?.committer?.date))
  .map((c) => ({
    sha: (c.sha || '').slice(0, 7),
    message: c.commit?.message?.split('\n')[0] || '',
    author: c.author?.login || c.commit?.author?.name || 'unknown',
    date: c.commit?.author?.date || c.commit?.committer?.date
  }));

const issues = collectRecords('Fetch Closed Issues')
  .filter((i) => !i.pull_request && inWeek(i.closed_at))
  .map((i) => ({ number: i.number, title: i.title, closedAt: i.closed_at }));

const prs = collectRecords('Fetch Merged PRs')
  .filter((p) => p.merged_at && inWeek(p.merged_at))
  .map((p) => ({ number: p.number, title: p.title, author: p.user?.login || 'unknown', mergedAt: p.merged_at }));

const contributors = new Set(commits.map((c) => c.author));

const instruction = config.language === 'FR'
  ? 'Rédigez un résumé narratif hebdomadaire en français. Structurez avec: Points forts, Commits, Issues résolues, PRs fusionnées, et TL;DR.'
  : 'Write a weekly narrative dev summary in English. Structure with: Highlights, Commits, Issues Resolved, Pull Requests Merged, and TL;DR.';

const activity = {
  repository: config.repoFullName,
  weekStart: config.weekStart,
  weekEnd: config.weekEnd,
  commits,
  closedIssues: issues,
  mergedPullRequests: prs
};

return [{
  json: {
    config,
    stats: {
      commits: commits.length,
      issues: issues.length,
      prs: prs.length,
      contributors: contributors.size
    },
    claudeRequest: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 2048,
      temperature: 0.3,
      system: 'You summarize GitHub development activity for engineering teams. Be accurate and do not invent work that is not present in the input data.',
      messages: [{
        role: 'user',
        content: `${instruction}\n\nRepository activity JSON:\n${JSON.stringify(activity, null, 2)}`
      }]
    }
  }
}];

const built = $('Build Claude Prompt').first().json;
const config = built.config;
const stats = built.stats;
const summary = ($json.content || []).map(part => part.text || '').join('\n').trim() || 'No summary generated.';

const title = `Weekly Dev Summary — ${config.repoFullName}`;
const period = `${config.weekStart.slice(0, 10)} → ${config.weekEnd.slice(0, 10)}`;
const statsLine = `${stats.commits} commits · ${stats.issues} issues closed · ${stats.prs} PRs merged · ${stats.contributors} contributors`;

return [{
  json: {
    config,
    title,
    period,
    statsLine,
    summary,
    markdown: `# ${title}\n*${period}*\n\n> ${statsLine}\n\n${summary}`,
    discordBody: {
      content: `**${title}**\n*${period}*\n${statsLine}\n\n${summary.slice(0, 1800)}`
    },
    slackBody: {
      blocks: [
        { type: 'header', text: { type: 'plain_text', text: title } },
        { type: 'section', text: { type: 'mrkdwn', text: `*${period}*\n${statsLine}` } },
        { type: 'section', text: { type: 'mrkdwn', text: summary.slice(0, 2800) } }
      ]
    },
    emailSubject: `${title} (${period})`,
    emailText: `${title}\n${period}\n${statsLine}\n\n${summary}`
  }
}];
